risks = [
    # (risk, likelihood 1-5, impact 1-5)
    ("Ransomware via unpatched VPN appliance", 4, 5),
    ("Lost laptop without disk encryption",    3, 4),
    ("Phishing steals staff email password",   5, 3),
    ("Web server outage on Black Friday",      2, 4),
]

def rate(score):
    if score >= 20:
        return "CRITICAL"
    if score >= 12:
        return "HIGH"
    if score >= 5:
        return "MEDIUM"
    return "LOW"

for name, likelihood, impact in sorted(risks, key=lambda r: r[1] * r[2], reverse=True):
    score = likelihood * impact
    print(f"{score:>2}  {rate(score):<8}  L={likelihood} I={impact}  {name}")
